SELECT FROM bko_role WHERE delete_state = 0 AND role_type = '003001' AND role_group = #{roleGroup,jdbcType=VARCHAR}
AND role_grade >= #{roleGrade}
AND role_name LIKE CONCAT('%',#{roleName},'%')
UNION SELECT
FROM bko_role WHERE delete_state = 0 AND institute_id = #{instituteId} AND role_type = '003003'
AND role_grade >= #{roleGrade}
AND role_name LIKE CONCAT('%',#{roleName},'%')

SELECT brole.*, institute.institute_name
FROM bko_role AS brole
LEFT JOIN inc_institute AS institute ON institute.id = brole.institute_id
WHERE brole.delete_state = 0
AND brole.role_grade >= #{roleGrade}

  AND brole.role_name LIKE CONCAT('%',#{roleName},'%')


  AND brole.institute_id = #{instituteId,jdbcType=VARCHAR}


  AND brole.institute_id IN

    #{item}



  AND brole.role_type = #{roleType,jdbcType=CHAR}


  AND brole.role_group = #{roleGroup,jdbcType=VARCHAR}

SELECT count(1)
FROM bko_role
WHERE delete_state = 0
  AND role_name = #{roleName,jdbcType=VARCHAR}
  AND institute_id = #{instituteId,jdbcType=VARCHAR}

  AND id != #{id,jdbcType=VARCHAR}
